	logger := stdoutLogger{}
	logger.Printf("dlq-replay starting: bucket=%s branch=%q skip_github_post=%v",
		*flagBucket, *flagBranch, *flagSkipGitHubPost)

	result, err := dlq.Replay(ctx, dlq.ReplayOptions{
		Bucket:         client.Bucket(*flagBucket),
		BranchFilter:   *flagBranch,
		SkipGitHubPost: *flagSkipGitHubPost,
		Logger:         logger,
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "replay failed: %v\n", err)
		os.Exit(1)
	}
	if result.Failed > 0 {
		os.Exit(1)
	}
}

// stdoutLogger writes one line per call to stdout.
type stdoutLogger struct{}

func (stdoutLogger) Printf(format string, args ...interface{}) {
	fmt.Fprintf(os.Stdout, format+"\n", args...)
}

